"use client";

import { useEffect } from "react";

/**
 * Registers the admin PWA service worker (public/sw.js, generated by next-pwa
 * on `next build`). Rendered only by the /admin layout, with scope /admin, so
 * the public site is never controlled by it. Does nothing in development,
 * where next-pwa doesn't generate sw.js.
 */
export function RegisterServiceWorker() {
  useEffect(() => {
    if (process.env.NODE_ENV !== "production" || !("serviceWorker" in navigator)) return;
    navigator.serviceWorker.register("/sw.js", { scope: "/admin" }).catch((err) => {
      console.warn("[pwa] Service worker registration failed:", err);
    });
  }, []);

  return null;
}
